import sys

def main():
    import sys
    n = int(sys.stdin.readline())
    permutation = list(map(int, sys.stdin.readline().split()))

    found = False
    for i in range(n - 2):
        a = permutation[i]
        b = permutation[i + 1]
        c = permutation[i + 2]
        if a < b / c < a or b / c > a > b / c:
            found = True
            break

    if found:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
